 const grassMat=mat('Meadow blades',0x7a955b,{side:THREE.DoubleSide}),reedMat=mat('Sedge and reed',0x7c8050,{side:THREE.DoubleSide}),leafMat=mat('River woodland foliage',0xb2bc9b),barkMat=mat('Willow bark',0x69604b),woodMat=mat('Weathered driftwood',0x716f59),siltMat=mat('Deep alluvial soil',0x454c40);
